using System;using System.Diagnostics;using System.IO;using System.Threading;using System.Threading.Tasks;
namespace SshScreen {
public static class NativeLifetimeChecks {
 static bool Alive(int pid){try{return !Process.GetProcessById(pid).HasExited;}catch{return false;}}
 static bool Gone(int pid){var w=Stopwatch.StartNew();while(Alive(pid)&&w.ElapsedMilliseconds<2500)Thread.Sleep(20);return !Alive(pid);}
 public static void Main(string[] args){string output=AppDomain.CurrentDomain.BaseDirectory;File.WriteAllText(Path.Combine(output,"native-lifetime-args.json"),new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(args));string root=Path.GetFullPath(args[0].Trim('"'));if(args.Length>1&&args[1]=="--owner"){using(var runtime=new PlayerRuntime(root)){File.WriteAllText(Path.Combine(root,"native-owner-child.txt"),runtime.Pid.ToString());Thread.Sleep(30000);}return;}
 var report=Wire.Map("ok",false,"game_input",false,"ssh_started",false);try{
 var profile=PlayerFiles.Load(Path.Combine(root,"players","current.json"));var own=new PlayerRuntime(root);int pid=own.Pid;var task=Task.Factory.StartNew(()=>{try{own.Initialize(profile);}catch{}});Thread.Sleep(40);var clock=Stopwatch.StartNew();own.Dispose();bool stopped=Gone(pid);report["cancel_loading_child_exited"]=stopped;report["cancel_loading_ms"]=clock.ElapsedMilliseconds;if(!stopped||!task.Wait(2500))throw new Exception("Startup cancellation left a worker");
 string receipt=Path.Combine(root,"native-owner-child.txt");if(File.Exists(receipt))File.Delete(receipt);var start=new ProcessStartInfo{FileName=Process.GetCurrentProcess().MainModule.FileName,Arguments="\""+root+"\" --owner",UseShellExecute=false,CreateNoWindow=true};using(var parent=Process.Start(start)){clock.Restart();while(!File.Exists(receipt)&&clock.ElapsedMilliseconds<5000)Thread.Sleep(20);if(!File.Exists(receipt))throw new Exception("Test owner did not initialize");int child=Int32.Parse(File.ReadAllText(receipt));parent.Kill();parent.WaitForExit(3000);report["owner_death_child_exited"]=Gone(child);if(!Wire.Bool(report,"owner_death_child_exited"))throw new Exception("Job did not release recognition child");}File.Delete(receipt);report["ok"]=true;
 }catch(Exception e){report["error"]=e.Message;Environment.ExitCode=1;}Wire.Save(Path.Combine(output,"native-lifetime.json"),report);Console.WriteLine(new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(report));}
}}
